import{z as i,x as o,o as t,c as p,q as A,j as s,D as E,d as r,s as l,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"威胁模型","description":"","frontmatter":{"title":"威胁模型","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/threat-model.md","filePath":"cs/threat-model.md","lastUpdated":1791413859000}'),d={name:"cs/threat-model.md"};function D(h,a,m,C,c,f){const B=o("Mermaid");return t(),p("div",null,[a[2]||(a[2]=A('<h1 id="威胁模型" tabindex="-1">威胁模型 <a class="header-anchor" href="#威胁模型" aria-label="Permalink to &quot;威胁模型&quot;">​</a></h1><div class="epigraph"><p>先写清谁能看、谁能改、谁能停，再选机制；没有敌手的「安全」只是口号。</p><footer>—— 据 Anderson, Security Engineering；Shostack 对威胁建模的整理</footer></div><p><a href="/cs/cia-triad">上一课</a>钉死三轴。本课不重定义保密。缺口是：三轴要对<strong>哪一类敌手</strong>成立。能窃听链路的人，与能跑同机进程的人，与能改 DNS 的人，不是同一场考试。后课每一种密码与隔离，都默认你已经会说「不防谁」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CIA 没有量化对象：无界全能敌手下没有可用系统。缺口不是列举攻击名称，而是画一张图：资产、入口、信任边界、敌手能力（被动窃听、主动改包、恶意端点、物理接触）。<a href="/cs/http-tls-entry">TLS 入口</a>防的是链路上的被动者加部分主动者，不防已攻破的浏览器。OS 隔离防的是用户态越权，不防同用户的漏洞代码。</p><p>本课不引入 STRIDE 的商标式背诵，只用「伪造、篡改、否认、信息泄露、拒绝服务、越权」当检查清单。</p><p><span class="marginnote">Kerckhoffs：系统的安全性应落在密钥保密，而不是算法隐瞒。威胁模型里「敌手知道算法」是默认，不是悲观。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写清：要保护的资产（密钥、库中元组、签名私钥）；敌手在边界外还是内；失败时优先保哪一轴。然后才映射到后课机制。假设崩溃的 2PC 与假设拜占庭的共识不是同一模型——本栏不把拜占庭共识插入主干，只标明 2PC 不在那一模型里。</p>',9)),(t(),s(n,null,{default:E(()=>[l(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ASSET%5B%22%E8%B5%84%E4%BA%A7%22%5D%20--%3E%20BND%5B%22%E4%BF%A1%E4%BB%BB%E8%BE%B9%E7%95%8C%22%5D%0A%20%20BND%20--%3E%20ADV%5B%22%E6%95%8C%E6%89%8B%E8%83%BD%E5%8A%9B%22%5D%0A%20%20ADV%20--%3E%20MAP%5B%22%E6%98%A0%E5%B0%84%E5%88%B0%E6%9C%BA%E5%88%B6%22%5D%0A%20%20MAP%20--%3E%20SYM%5B%22%E5%90%8E%E8%AF%BE%3A%20%E5%AF%B9%E7%A7%B0%E5%8A%A0%E5%AF%86%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"同一机制在不同模型下结论相反。加密在「只能看链路」下给保密；在「能看内存」下不够。完整性在「能改包」下要 MAC；在「能拿签名私钥」下要撤销与旋转。把模型写进设计，后课才不会把 TLS 当成「整机安全」。",-1)),a[5]||(a[5]=e("p",null,"同一把加密，换一档敌手结论怎么变：",-1)),(t(),s(n,null,{default:E(()=>[l(B,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E9%83%A8%E7%BD%B2%E4%BA%86%E9%93%BE%E8%B7%AF%E5%8A%A0%E5%AF%86%22%5D%20--%3E%20Q1%7B%22%E6%95%8C%E6%89%8B%E8%83%BD%E8%AF%BB%E6%9C%8D%E5%8A%A1%E5%99%A8%E5%86%85%E5%AD%98%3F%22%7D%0A%20%20Q1%20--%3E%7C%22%E4%B8%8D%E8%83%BD%22%7C%20OK%5B%22%E9%93%BE%E8%B7%AF%E4%B8%8E%E7%AB%AF%E7%82%B9%E9%83%BD%E4%BF%9D%E5%AF%86%3A%20%E6%88%90%E7%AB%8B%22%5D%0A%20%20Q1%20--%3E%7C%22%E8%83%BD%22%7C%20BAD%5B%22%E5%AF%86%E9%92%A5%E5%B0%B1%E5%9C%A8%E5%86%85%E5%AD%98%E9%87%8C%3A%20%E4%B8%8D%E5%A4%9F%22%5D%0A%20%20BAD%20--%3E%20NEED%5B%22%E8%A6%81%E5%86%8D%E5%8A%A0%E8%BE%B9%E7%95%8C%3A%20%E6%B2%99%E7%AE%B1%E6%88%96%E7%A1%AC%E4%BB%B6%E9%9A%94%E7%A6%BB%22%5D%0A%20%20OK%20--%3E%20Q2%7B%22%E6%95%8C%E6%89%8B%E8%83%BD%E6%94%B9%E5%8C%85%3F%22%7D%0A%20%20Q2%20--%3E%7C%22%E8%83%BD%22%7C%20MAC%5B%22%E4%BF%9D%E5%AF%86%E4%B9%8B%E5%A4%96%E8%BF%98%E8%A6%81%20MAC%20%E6%88%96%E7%AD%BE%E5%90%8D%22%5D%0A%20%20Q2%20--%3E%7C%22%E4%B8%8D%E8%83%BD%22%7C%20ENOUGH%5B%22%E6%9C%AC%E6%A8%A1%E5%9E%8B%E5%86%85%E6%9C%BA%E5%88%B6%E5%B7%B2%E5%A4%9F%E7%94%A8%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p><span class="marginnote">常见误区：初学者容易以为「用了 TLS 就安全了」——TLS 只覆盖链路这一段。浏览器被植入木马、服务器内存被读走时，明文终点和钥匙都在敌手手里：不是机制失效，是敌手能力已经换了一档，模型没跟着换。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>威胁模型会过时：侧信道把「看不到内存」改成「能测时间」。本课承认模型是假设，不是物理定律。也不把渗透清单当模型：清单是测试，模型是规格。</p><p>信任边界画错（把同一主机上的进程当成外部敌手或相反）会让后课沙箱与 TLS 的分工错位。后课默认：谈到采用某种密码，先有敌手能力；对称加密服务的是共享密钥已安全分发的那一类场景。</p><p><span class="marginnote">术语翻译：「信任边界」就是数据从不可信区进入可信区的那道门——网卡进内核、用户输入进服务端都算。敌手能力按「在门内还是在门外」来定义，而不是按物理位置：同一台机器上的另一个进程可能在门外，也可能已被攻破在门内。</span></p><p>写不清「不防谁」，后课公钥与沙箱都会被误读成全能。模型宁可窄而真，不要宽而假。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>Kerckhoffs：敌手知道算法，秘密在密钥与边界。</p></li><li><p>后课对称加密只服务「能看密文、没有密钥」这一档。</p></li><li><p>CIA 是轴；本课补敌手、边界、资产。</p></li><li><p>算法公开、密钥保密是默认假设。</p></li><li><p>共享密钥下的保密机制，下一课才讲。</p></li><li><p>出处：Anderson, <em>Security Engineering</em>；Kerckhoffs, 1883。</p></li></ul><p><span class="marginnote">直觉类比：威胁模型像买保险前先读清险种条款——盗抢险不赔泡水。把「敌手能窃听但不能改包」写成一行显式假设，选机制时才知道手上的工具够不够，出事时也知道该怪假设还是怪实现。</span></p>',9))])}const _=i(d,[["render",D]]);export{S as __pageData,_ as default};
